const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const colors=['#1f63db','#b75d2b','#7751b8','#007f8a','#c34770','#3f7994','#628234','#536eb8','#967047','#7c5b8c','#657b3b','#b25b76'];let lines=[],schedules={},routes={},journeys={},journeyId=null,referenceLayers=null,referenceMarkers={},stops=[],stopLayers=null,stopMarkers={},selected=null,favorites=[],onlyFavorites=false,filter='Todas',map=null,layers=null,userLayer=null,installPrompt=null;let direction=0,day='week',tab='map',variantFilter='all';try{favorites=JSON.parse(localStorage.getItem('rm-favs')||'[]')}catch{}const url=new URL(location.href);direction=url.searchParams.get('sentido')==='1'?1:0;let nowParts;function clock(){return Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:'America/Sao_Paulo',weekday:'short',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date()).map(x=>[x.type,x.value]))}nowParts=clock();const currentDay=nowParts.weekday==='Sun'?'sun':nowParts.weekday==='Sat'?'sat':'week';day=['week','sat','sun','tuewedfri'].includes(url.searchParams.get('dia'))?url.searchParams.get('dia'):currentDay;
