function setTab(t){tab=t;for(const key of ['times','map','stops']){$('#'+(key==='times'?'timespanel':key==='map'?'mappanel':'stopspanel')).hidden=key!==t;$('#tab-'+key).setAttribute('aria-selected',key===t)}if(t==='map')renderMap();if(t==='stops')renderStops()}
function initMap(){if(map)return true;if(!window.L){$('#map').textContent='Não foi possível iniciar o mapa. Os horários continuam disponíveis.';return false}map=L.map('map',{scrollWheelZoom:false}).setView([-24.49,-47.845],13);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(map).on('tileerror',()=>{$('#mapnote').textContent='O mapa de fundo não carregou. Verifique sua conexão. Os traçados salvos podem continuar visíveis.'});layers=L.featureGroup().addTo(map);stopLayers=L.featureGroup().addTo(map);referenceLayers=L.featureGroup().addTo(map);return true}
function currentJourney(){if(!selected)return null;const options=(journeys[selected.id]||[]).filter(j=>j.direction===direction);return options.find(j=>j.id===journeyId)||options.find(j=>j.kind==='regular')||options.find(j=>j.kind==='partial')||options[0]||null}
function syncJourneyControls(){const journey=currentJourney();journeyId=journey?.id||null;const options=(journeys[selected?.id]||[]).filter(j=>j.direction===direction);$('#journeyselect').innerHTML=options.map(j=>`<option value="${esc(j.id)}">${esc(j.label)}</option>`).join('');$('#journeyselect').value=journeyId||'';$('#journeyselect').disabled=!options.length}
