function renderItineraryPanel(){const j=currentJourney();const mapped=j?.points.filter(p=>p.position).length||0;$('#itinerary').innerHTML=`<div class="itinerarysummary"><div><h3>${esc(j?.label||'Percurso não informado')}</h3><p>${j?.points.length||0} referências na sequência · ${mapped} com localização aproximada</p></div><button id="openpoints">Ver todos os pontos do trajeto →</button></div><p class="hint">Os números indicam referências do itinerário. O cadastro de locais exatos para embarque ainda não está validado.</p>`;$('#openpoints').onclick=()=>setTab('stops')}
function referencePopup(point){const pos=point.position;return `<div class="referencepopup"><span class="popup-tag">REFERÊNCIA ${point.sequence} · EMBARQUE NÃO VALIDADO</span><h4>${esc(point.label)}</h4><p>Localização aproximada de rua, bairro ou estabelecimento. Não identifica o poste ou o lado de embarque.</p>${pos?`<p>Local encontrado: ${esc(pos.matchedName)}<br>${pos.lat.toFixed(6)}, ${pos.lon.toFixed(6)}</p><a href="${esc(pos.source)}" target="_blank" rel="noopener">Fonte geográfica ↗</a><br><a href="${esc(streetView({lat:pos.lat,lon:pos.lon}))}" target="_blank" rel="noopener">Procurar vista da rua ↗</a>`:''}</div>`}
function renderReferenceMarkers(){if(!referenceLayers)return;referenceLayers.clearLayers();referenceMarkers={};if(!$('#showrefs').checked)return;const groups=new Map();for(const point of currentJourney()?.points||[]){if(!point.position)continue;const key=point.position.lat.toFixed(6)+','+point.position.lon.toFixed(6);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(point)}for(const grouped of groups.values()){const pos=grouped[0].position,number=grouped.map(p=>p.sequence).join('·');const marker=L.marker([pos.lat,pos.lon],{icon:L.divIcon({className:'route-reference-marker',html:esc(number),iconSize:[Math.max(29,number.length*7+12),29],iconAnchor:[14,14]}),title:grouped.map(p=>p.sequence+'. '+p.label).join(' / ')+' · referências, não paradas validadas'}).addTo(referenceLayers).bindPopup(grouped.map(referencePopup).join('<hr>'));for(const point of grouped)referenceMarkers[point.id]=marker}}
function renderMap(){if(!initMap())return;syncJourneyControls();map.invalidateSize();layers.clearLayers();renderStopMarkers();renderReferenceMarkers();const j=currentJourney();$('#maptitle').textContent=selected?selected.id+' · '+directionName():'Mapa de Registro';const route=routes[selected?.id],shape=j?.kind==='regular'?route?.variants?.find(x=>x.direction===direction):null;const visible=shape&&$('#showshape').checked;const count=j?.points.filter(p=>p.position).length||0;$('#fit').disabled=!visible&&!count;$('.legend').hidden=!visible;document.documentElement.style.setProperty('--route-marker-color',selected?.color||'#2764ee');if(visible){L.geoJSON(shape.geometry,{style:{color:'white',weight:8,opacity:.9}}).addTo(layers);L.geoJSON(shape.geometry,{style:{color:selected.color,weight:4,dashArray:'9 8',opacity:1}}).addTo(layers)}$('#mapnote').textContent=j?`${count} de ${j.points.length} referências deste percurso têm localização aproximada. Os demais itens continuam na lista. ${visible?'A linha tracejada é uma estimativa, não um traçado oficial.':'Sem traçado viário publicado para esta variante; os marcadores não foram ligados por uma rota inventada.'} Confirme o local exato de embarque com a operadora.`:'Sem sequência publicada para esta seleção.';renderItineraryPanel();fit()}
function streetView(stop){return 'https://www.google.com/maps/@?'+new URLSearchParams({api:'1',map_action:'pano',viewpoint:stop.lat+','+stop.lon})}
function popupStop(stop){return `<div class="stop-popup"><b>${esc(stop.name)}</b><p>Mapeado no OpenStreetMap. Sem confirmação da operadora ou das linhas atendidas.</p><a href="${esc(stop.source)}" target="_blank" rel="noopener">Conferir registro do local ↗</a><br><a href="${esc(streetView(stop))}" target="_blank" rel="noopener">Procurar vista da rua ↗</a><small>A imagem pode não estar disponível ou ser de outra data.</small></div>`}
