function distanceTo(stop){if(!userPosition)return null;const rad=x=>x*Math.PI/180,a=rad(stop.lat-userPosition.latitude),b=rad(stop.lon-userPosition.longitude);const h=Math.sin(a/2)**2+Math.cos(rad(userPosition.latitude))*Math.cos(rad(stop.lat))*Math.sin(b/2)**2;return 6371000*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h))}
