$('#showstops').onchange=renderMap;$('#showrefs').onchange=renderMap;$('#showshape').onchange=renderMap;

function fit(){const pts=(currentJourney()?.points||[]).filter(p=>p.position).map(p=>[p.position.lat,p.position.lon]);if(pts.length)map.fitBounds(pts,{padding:[35,35],maxZoom:15});else if(layers?.getLayers().length)map.fitBounds(layers.getBounds(),{padding:[35,35],maxZoom:15})}$('#fit').onclick=fit;let locationWatch=null,userPosition=null,accuracyLayer=null,locationSession=0;
function locationLabel(text,active=false){$('#locationstatus').textContent=text;$('.locationbox').classList.toggle('active',active);$('#stoplocation').hidden=!active;$('#startlocation strong').textContent=active?'Minha localização ativa':'Usar minha localização';$('#startlocation small').textContent=active?'Toque para voltar à sua posição':'Veja onde você está no mapa'}
function stopLocation(message='Localização desativada. Você pode continuar consultando as linhas.') {locationSession++;if(locationWatch!==null&&navigator.geolocation)navigator.geolocation.clearWatch(locationWatch);locationWatch=null;userPosition=null;if(userLayer&&map)map.removeLayer(userLayer);if(accuracyLayer&&map)map.removeLayer(accuracyLayer);userLayer=null;accuracyLayer=null;locationLabel(message,false);$('#userlive').textContent='Sua posição: desativada';renderStops();}
function startLocation(){setTab('map');if(!initMap())return;if(window.isSecureContext===false){locationLabel('Abra o portal pelo endereço HTTPS para usar a localização.');return}if(!navigator.geolocation){locationLabel('Este navegador não oferece localização. Você pode consultar as linhas manualmente.');return}if(userPosition){map.setView([userPosition.latitude,userPosition.longitude],16);return}if(locationWatch!==null)return;locationLabel('Aguardando sua autorização e o sinal de localização…',true);const session=++locationSession;let first=true;locationWatch=navigator.geolocation.watchPosition(p=>{if(session!==locationSession)return;const {latitude,longitude,accuracy}=p.coords;if(!Number.isFinite(latitude)||!Number.isFinite(longitude)||!Number.isFinite(accuracy))return;userPosition={latitude,longitude,accuracy,timestamp:p.timestamp};const latlng=[latitude,longitude];if(userLayer)userLayer.setLatLng(latlng);else userLayer=L.marker(latlng,{icon:L.divIcon({className:'user-dot',html:'',iconSize:[20,20],iconAnchor:[10,10]}),title:'Você está aqui'}).addTo(map).bindPopup('Você está aqui · posição aproximada');if(accuracyLayer)accuracyLayer.setLatLng(latlng).setRadius(accuracy);else accuracyLayer=L.circle(latlng,{radius:accuracy,color:'#2764ee',weight:1,fillColor:'#2764ee',fillOpacity:.08,interactive:false}).addTo(map);if(first){map.setView(latlng,accuracy>1000?13:16);first=false}const precision=accuracy>=1000?(accuracy/1000).toFixed(1)+' km':Math.round(accuracy)+' m';const outside=latitude<-24.8||latitude>-24.2||longitude<-48.2||longitude>-47.4;if(tab!=='stops')renderStops();$('#userlive').textContent='Sua posição: atualizada às '+new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});locationLabel('Você é o ponto azul. Precisão aproximada: '+precision+'.'+(outside?' Você está fora da região de Registro.':accuracy>200?' O sinal está impreciso; tente uma área aberta.':''),true)},error=>{if(session!==locationSession)return;const messages={1:'Acesso à localização não autorizado. Para tentar novamente, permita a localização nas configurações deste site no navegador.',2:'Não foi possível encontrar sua posição. Confira se a localização do aparelho está ligada e tente novamente.',3:'A localização demorou para responder. Tente novamente, de preferência em uma área aberta.'};stopLocation(messages[error.code]||'Localização indisponível. Tente novamente ou consulte as linhas manualmente.')},{enableHighAccuracy:true,timeout:15000,maximumAge:10000});}
$('#locate').onclick=startLocation;$('#startlocation').onclick=startLocation;$('#stoplocation').onclick=()=>stopLocation();window.addEventListener('pagehide',()=>stopLocation());document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&locationWatch!==null)stopLocation('Localização pausada. Toque em “Usar minha localização” para retomar.');});

async function share(){try{if(navigator.share)await navigator.share({title:'Linha '+selected.id+' — Registro Mobilidade',url:location.href});else if(navigator.clipboard){await navigator.clipboard.writeText(location.href);toast('Link da linha copiado.')}else toast('Copie o endereço desta página para compartilhar.')}catch(e){if(e.name!=='AbortError')toast('Copie o endereço desta página para compartilhar.')}}
$('#lines').onclick=e=>{const star=e.target.closest('[data-star]'),pick=e.target.closest('[data-line]');if(star)toggleFavorite(star.dataset.star);else if(pick)selectLine(pick.dataset.line,true)};$('#search').oninput=renderList;$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;updateFilters();renderList()});$('#favonly').onclick=()=>{onlyFavorites=!onlyFavorites;updateFilters();renderList()};$('#tab-times').onclick=()=>setTab('times');$('#tab-map').onclick=()=>setTab('map');$('#tab-stops').onclick=()=>setTab('stops');$$('[role=tab]').forEach(b=>b.onkeydown=e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();const keys=['times','map','stops'];setTab(keys[(keys.indexOf(tab)+(e.key==='ArrowRight'?1:2))%3]);$('#tab-'+tab).focus()}});$('#help').onclick=()=>$('#helpdialog').showModal();$('#closehelp').onclick=()=>$('#helpdialog').close();$('#helpdialog').onclick=e=>{if(e.target===$('#helpdialog'))$('#helpdialog').close()};window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});$('#install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null}else toast('No menu do navegador, escolha “Instalar aplicativo” ou “Adicionar à Tela de Início”.')};function connection(){$('#connection').textContent=navigator.onLine?'● Online':'○ Sem internet';$('#offlineinfo').textContent=navigator.onLine?'Fontes consultadas em 20/10/2026':'Modo offline · imagens externas e mapa precisam de internet'}connection();window.addEventListener('online',connection);window.addEventListener('offline',connection);$('#date').textContent=new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',day:'numeric',month:'long'}).format(new Date());
Promise.all(['lines.json','schedules.json','routes.json','stops.json','journeys.json'].map(f=>fetch(f).then(r=>{if(!r.ok)throw Error(f);return r.json()}))).then(([l,s,r,st,j])=>{lines=l.map((x,i)=>({...x,color:colors[i%colors.length]}));schedules=s;routes=r;stops=st;journeys=j;renderList();if(lines.some(x=>x.id===url.searchParams.get('linha')))selectLine(url.searchParams.get('linha'));else selectLine('L3');setTab('map');}).catch(()=>{$('#lines').innerHTML='<p class="alert">Não foi possível carregar os dados. Conecte-se e recarregue a página.</p>'});if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>toast('Seu navegador não disponibilizou o modo offline.'));setInterval(()=>{if(selected&&!document.querySelector('#schedule details[open]'))renderSchedule()},60000);
